const l = $('Leer Liquidación').item.json;
const d = typeof l.detalle_calculo === 'string' ? JSON.parse(l.detalle_calculo) : (l.detalle_calculo || {});

const IVA = 0.21;
const r2 = n => Math.round((n + Number.EPSILON) * 100) / 100;
const num = v => parseFloat(v) || 0;
const eur = n => {
  const [i, dec] = Math.abs(n).toFixed(2).split('.');
  return (n < 0 ? '-' : '') + i.replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ',' + dec + ' €';
};

const fechaCorregida = new Date(new Date(l.mes).getTime() + 24 * 60 * 60 * 1000);
const meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const mesNombre = `${meses[fechaCorregida.getUTCMonth()]} de ${fechaCorregida.getUTCFullYear()}`;

const ingresos = num(l.ingresos), gastos = num(l.gastos), honorarios = num(l.honorarios_gestion);
const ivaTotal = num(l.iva), rotaciones = num(l.rotaciones), reparaciones = num(l.reparaciones), neto = num(l.neto_propietario);
const cobroDirecto = !!d.nota_cobro_directo;

// Desglose de lo que se descuenta en la liquidación
const rotTrad = num(d.rotaciones_tradicional_deducida);
const rotHab = r2(rotaciones - rotTrad);
let colab = r2(ivaTotal / IVA - (honorarios + gastos + reparaciones + rotaciones)); // colaboradores repercutidos
if (Math.abs(colab) < 0.05) colab = 0;
const otros = r2(gastos + colab);

const mkFila = (c, s) => { const iva = r2(s * IVA); return { c, s, iva, t: r2(s + iva) }; };
const filaHtml = f => `<tr><td>${f.c}</td><td class="n">${eur(f.s)}</td><td class="n">${eur(f.iva)}</td><td class="n">${eur(f.t)}</td></tr>`;
const suma = (rows, k) => r2(rows.reduce((a, f) => a + f[k], 0));

// Bloque 1: factura mensual descontada de liquidación
const mes = [
  mkFila('Honorarios de gestión', cobroDirecto ? 0 : honorarios),
  mkFila('Rotación habitación propietario', rotHab),
  mkFila('Rotación tradicional propietario', rotTrad),
  mkFila('Reparación y conservación', reparaciones),
  mkFila('Otros cargos compensados', otros),
];
const totMes = { s: suma(mes, 's'), iva: suma(mes, 'iva'), t: suma(mes, 't') };

let controlTxt = '—', controlAviso = false;
if (!cobroDirecto && l.estado !== 'factura_aparte') {
  let ctrl = r2(ingresos - neto - totMes.t);
  if (Math.abs(ctrl) < 0.05) ctrl = 0;
  controlTxt = eur(ctrl);
  controlAviso = ctrl !== 0;
}

// Bloque 2: cuenta a cobrar / facturas aparte
const sumaArr = (arr, k) => (arr || []).reduce((a, x) => a + num(x[k]), 0);
const aparte = [
  mkFila('Gestión — propietario cobra directamente', cobroDirecto ? honorarios : 0),
  mkFila('Rotación tradicional propietario', r2(sumaArr(d.rotaciones_tradicional_factura_aparte, 'base'))),
  mkFila('Rotación habitación propietario', 0),
  mkFila('Reparación y conservación', r2(sumaArr(d.reparaciones_factura_aparte, 'facturado'))),
  mkFila('Otro cargo a propietario', 0),
];
const totAparte = { s: suma(aparte, 's'), iva: suma(aparte, 'iva'), t: suma(aparte, 't') };

const modalidad = d.tipo_gestion ? d.tipo_gestion.charAt(0).toUpperCase() + d.tipo_gestion.slice(1) : '';

const html = `
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: Arial, sans-serif; padding: 36px; color: #1a1a1a; font-size: 13px; }
  h1 { font-size: 16px; color: #1f3864; margin: 0 0 4px 0; }
  .sub { color: #555; margin-bottom: 18px; }
  table { width: 100%; border-collapse: collapse; margin-bottom: 18px; }
  td { padding: 6px 8px; border-bottom: 1px solid #d9d9d9; }
  .n { text-align: right; white-space: nowrap; }
  .info td { background: #ddebf7; border-bottom: 1px solid #fff; }
  .info td:first-child { font-weight: bold; width: 28%; }
  .bar td { background: #1f3864; color: #fff; font-weight: bold; text-align: center; letter-spacing: .3px; }
  .head td { background: #ddebf7; font-weight: bold; text-align: center; }
  .tot td { background: #e2efda; font-weight: bold; }
  .ctl td { background: #f2f7fb; }
  .gen td { background: #fff2cc; font-weight: bold; }
  .aviso { background: #fff2cc; border: 1px solid #ffc107; padding: 10px; margin-top: 10px; font-size: 12px; font-style: italic; }
</style>
</head>
<body>
  <h1>Liquidación mensual — ${mesNombre}</h1>
  <div class="sub">${l.direccion} (${l.codigo_rentila})</div>

  <table class="info">
    <tr><td>Propietario</td><td>${l.propietario_nombre || ''}</td></tr>
    <tr><td>Modalidad</td><td>${modalidad}</td></tr>
    <tr><td>Cobra alquiler</td><td>${cobroDirecto ? 'Propietario' : 'Management Co.'}</td></tr>
  </table>

  <table>
    <tr class="bar"><td colspan="4">FACTURA MENSUAL — DESCONTADA DE LIQUIDACIÓN</td></tr>
    <tr class="head"><td>Concepto</td><td>Subtotal</td><td>IVA</td><td>Total</td></tr>
    ${mes.map(filaHtml).join('')}
    <tr class="tot"><td>TOTAL FACTURA SPEEDINVOICE</td><td class="n">${eur(totMes.s)}</td><td class="n">${eur(totMes.iva)}</td><td class="n">${eur(totMes.t)}</td></tr>
    <tr class="ctl"><td colspan="3">CONTROL: debe ser 0,00 €</td><td class="n">${controlTxt}</td></tr>
  </table>
  ${controlAviso ? `<div class="aviso">Si el control no es 0,00 €, revisa REGISTRO antes de facturar.</div>` : ''}

  <table>
    <tr class="bar"><td colspan="4">CUENTA A COBRAR / FACTURAS APARTE</td></tr>
    <tr class="head"><td>Concepto</td><td>Subtotal</td><td>IVA</td><td>Total</td></tr>
    ${aparte.map(filaHtml).join('')}
    <tr class="gen"><td>TOTAL GENERADO ESTE MES</td><td class="n">${eur(totAparte.s)}</td><td class="n">${eur(totAparte.iva)}</td><td class="n">${eur(totAparte.t)}</td></tr>
  </table>

  ${l.estado === 'pendiente' ? `<div class="aviso">Esta liquidación tiene movimientos pendientes de revisión manual antes de cerrarse definitivamente.</div>` : ''}
  ${cobroDirecto ? `<div class="aviso">El inquilino paga el alquiler directamente al propietario. La gestora no transfiere ningún importe: los honorarios de gestión se facturan aparte.</div>` : ''}
</body>
</html>
`;
return [{ json: { html: html, propiedad_id: l.propiedad_id, mes: l.mes } }];

const l = $input.first().json;

const fechaOriginal = new Date(l.mes);
const fechaCorregida = new Date(fechaOriginal.getTime() + 24 * 60 * 60 * 1000);
const meses = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
const mesNombre = `${meses[fechaCorregida.getUTCMonth()]} ${fechaCorregida.getUTCFullYear()}`;

const ivaPct = 0.21;
const detalle = typeof l.detalle_calculo === 'string' ? JSON.parse(l.detalle_calculo) : l.detalle_calculo;

const num = v => parseFloat(v) || 0;
const r2 = n => Math.round((n + Number.EPSILON) * 100) / 100;
const mkConcepto = (concepto, subtotal) => {
  const s = r2(subtotal);
  const iva = r2(s * ivaPct);
  return { concepto, subtotal: s, iva, total: r2(s + iva) };
};

// Construir líneas de concepto, cada una con su propio subtotal/IVA/total
const conceptos = [];

if (l.honorarios_gestion > 0) {
  const subtotal = parseFloat(l.honorarios_gestion);
  conceptos.push({
    concepto: 'Honorarios de gestión',
    subtotal: subtotal,
    iva: Math.round(subtotal * ivaPct * 100) / 100,
    total: Math.round(subtotal * (1 + ivaPct) * 100) / 100
  });
}

const rotTrad = num(detalle.rotaciones_tradicional_deducida);
const rotHab = r2(num(l.rotaciones) - rotTrad);
if (rotHab > 0) conceptos.push(mkConcepto('Rotación habitación propietario', rotHab));
if (rotTrad > 0) conceptos.push(mkConcepto('Rotación tradicional propietario', rotTrad));

if (detalle.reparaciones_detalle && detalle.reparaciones_detalle.length > 0) {
  const subtotalRep = detalle.reparaciones_detalle.reduce((s, r) => s + r.facturado, 0);
  conceptos.push({
    concepto: 'Reparación y conservación',
    subtotal: Math.round(subtotalRep * 100) / 100,
    iva: Math.round(subtotalRep * ivaPct * 100) / 100,
    total: Math.round(subtotalRep * (1 + ivaPct) * 100) / 100
  });
}

let colab = r2(num(l.iva) / ivaPct - (num(l.honorarios_gestion) + num(l.gastos) + num(l.reparaciones) + num(l.rotaciones)));
if (Math.abs(colab) < 0.05) colab = 0;
const otros = r2(num(l.gastos) + colab);
if (otros > 0) conceptos.push(mkConcepto('Otros cargos compensados', otros));

const totalFactura = conceptos.reduce((s, c) => s + c.total, 0);
const totalSubtotal = conceptos.reduce((s, c) => s + c.subtotal, 0);
const totalIva = conceptos.reduce((s, c) => s + c.iva, 0);

const tablaTexto = conceptos.map(c =>
  `${c.concepto.padEnd(35)} ${c.subtotal.toFixed(2).padStart(10)}€ ${c.iva.toFixed(2).padStart(10)}€ ${c.total.toFixed(2).padStart(10)}€`
).join('\n');

const textoParaCopiar = `
CLIENTE: ${l.propietario_nombre || '⚠️ SIN ASIGNAR'}
NIF: ${l.propietario_nif || '⚠️ SIN ASIGNAR'}
EMAIL: ${l.propietario_email || '⚠️ SIN ASIGNAR'}
CONCEPTO GENERAL: Gestión ${l.direccion} — ${mesNombre}

${'Concepto'.padEnd(35)} ${'Subtotal'.padStart(11)} ${'IVA'.padStart(11)} ${'Total'.padStart(11)}
${tablaTexto}
${'-'.repeat(70)}
${'TOTAL FACTURA SPEEDINVOICE'.padEnd(35)} ${totalSubtotal.toFixed(2).padStart(10)}€ ${totalIva.toFixed(2).padStart(10)}€ ${totalFactura.toFixed(2).padStart(10)}€
`.trim();

return [{
  json: {
    cliente_nombre: l.propietario_nombre,
    cliente_nif: l.propietario_nif,
    cliente_email: l.propietario_email,
    conceptos: conceptos,
    total_subtotal: Math.round(totalSubtotal * 100) / 100,
    total_iva: Math.round(totalIva * 100) / 100,
    total_factura: Math.round(totalFactura * 100) / 100,
    texto_para_copiar: textoParaCopiar
  }
}];

parameters.query:
UPDATE liquidaciones
SET datos_speedinvoice = '{{ $json.texto_para_copiar.replace(/'/g, "''") }}'
WHERE id = {{ $('Leer Liquidación').item.json.id }};

