const items = $input.all().map(i => i.json);

const result = items.map(r => {
  const ivaPct = parseFloat(r.iva_pct);
  const tarifaInquilino = parseFloat(r.tarifa_inquilino);
  const montoOriginal = parseFloat(r.monto) || 0;
  const subtotal = montoOriginal > 0 ? montoOriginal : tarifaInquilino;
  const iva = Math.round(subtotal * ivaPct * 100) / 100;
  const total = Math.round((subtotal + iva) * 100) / 100;

  const texto = `
CLIENTE: ${r.de_a}
CONCEPTO: Gestión alquiler — ${r.direccion}
${r.descripcion}

Subtotal: ${subtotal.toFixed(2)}€
IVA (21%): ${iva.toFixed(2)}€
TOTAL: ${total.toFixed(2)}€
`.trim();

  return { json: { movimiento_id: r.id, cliente: r.de_a, subtotal, iva, total, texto_factura_inquilino: texto } };
});

return result;

const l = $input.first().json;
const detalle = typeof l.detalle_calculo === 'string' ? JSON.parse(l.detalle_calculo) : l.detalle_calculo;
const ivaPct = 0.21;

const conceptosAparte = [];

// Caso: cobro directo al propietario — los honorarios se facturan aparte
if (detalle.nota_cobro_directo) {
  const base = parseFloat(l.honorarios_gestion);
  const iva = Math.round(base * ivaPct * 100) / 100;
  conceptosAparte.push({
    concepto: 'Honorarios de gestión (cobro directo al propietario)',
    base: base,
    iva: iva,
    total: Math.round((base + iva) * 100) / 100
  });
}

// Reparaciones que superan el umbral
if (detalle.reparaciones_factura_aparte) {
  for (const r of detalle.reparaciones_factura_aparte) {
    const iva = Math.round(r.facturado * ivaPct * 100) / 100;
    conceptosAparte.push({
      concepto: `Reparación: ${r.concepto}`,
      base: r.facturado,
      iva: iva,
      total: r.facturado_con_iva
    });
  }
}

// Rotación tradicional que supera el umbral
if (detalle.rotaciones_tradicional_factura_aparte) {
  for (const r of detalle.rotaciones_tradicional_factura_aparte) {
    const iva = Math.round(r.base * ivaPct * 100) / 100;
    conceptosAparte.push({
      concepto: `Rotación tradicional: ${r.concepto}`,
      base: r.base,
      iva: iva,
      total: r.con_iva
    });
  }
}

if (conceptosAparte.length === 0) {
  return [{ json: { sin_facturas_aparte: true, texto_factura_aparte: null } }];
}

const totalGeneral = conceptosAparte.reduce((s, c) => s + c.total, 0);

const tabla = conceptosAparte.map(c =>
  `${c.concepto.padEnd(45)} ${c.base.toFixed(2).padStart(10)}€ ${c.iva.toFixed(2).padStart(10)}€ ${c.total.toFixed(2).padStart(10)}€`
).join('\n');

const texto = `
FACTURA APARTE — ${l.direccion}
(No se descuenta de la liquidación mensual)

${'Concepto'.padEnd(45)} ${'Base'.padStart(11)} ${'IVA'.padStart(11)} ${'Total'.padStart(11)}
${tabla}
${'-'.repeat(80)}
${'TOTAL A FACTURAR APARTE'.padEnd(45)} ${' '.repeat(11)} ${' '.repeat(11)} ${totalGeneral.toFixed(2).padStart(10)}€
`.trim();

return [{ json: { conceptos: conceptosAparte, total: Math.round(totalGeneral * 100) / 100, texto_factura_aparte: texto } }];

const datos = $('Leer Liquidación').all();
const ultimo = datos[datos.length - 1].json;

return [{
  json: {
    propiedad_id: ultimo.propiedad_id,
    liquidacion_id: ultimo.id,
    direccion: ultimo.direccion
  }
}];
